276	    private Claim changeStatus(String sheetId, String user, Long id, ClaimStatus next, String reason,
277	            boolean judgedOnOriginal, AsOf asOf) {
278	        // Opening takes the sheet's next number, locking the sheet first so the claim is read only
279	        // once no other open on the sheet is under way; a refusal rolls the number back.
280	        Sheet numbering = next == ClaimStatus.OPEN ? sheets.lockForNumbering(sheetId) : null;
281	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
282	        String action = switch (next) {
283	            case OPEN -> "open";
284	            case SETTLED -> "settle";
285	            case VOID -> "void";
286	            default -> throw new ClaimStatusRefusedException();
287	        };
288	        if (!settings.mayDo(sheetId, user, action)) throw new ClaimNotPermittedException();
289	        boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
290	        if (voidingSettled) refuseVoidOfSettled(sheetId, user, claim);
291	        else if (!claim.getStatus().canBecome(next)) {
292	            throw new ClaimStatusRefusedException();
293	        }
294	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) {
295	            throw new ClaimDeferredException();
296	        }
297	        if (next == ClaimStatus.SETTLED && !judgedOnOriginal && claim.isOpenedOrEditedBy(user)) {
298	            throw new ClaimSettledByOpenerException();
299	        }
300	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
301	        if (next == ClaimStatus.OPEN && person.flagOn(sheets.today(sheetId)) != null
302	                && settings.roleOf(sheetId, user) != Role.STEWARD) {
303	            throw new ClaimFlaggedException();
304	        }
305	        // Settling freezes the late charge of the moment (as of a date: of the end of that date) into the settled due.
306	        BigDecimal settling = next != ClaimStatus.SETTLED ? null
307	                : asOf != null ? asOf.figure() : chargedFigureOf(sheetId, person, claim);
308	        if (next == ClaimStatus.SETTLED && !judgedOnOriginal) refuseUnproved(sheetId, person, claim, settling);
309	        BigDecimal opening = next == ClaimStatus.OPEN ? chargedFigureOf(sheetId, person, claim) : null;
310	        if (next == ClaimStatus.OPEN) refuseUnnoted(sheetId, claim, opening);
311	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, person, settling)) next = ClaimStatus.PENDING;
312	        String voidReason = next == ClaimStatus.VOID ? voidReasons.reasonForVoid(sheetId, reason) : null;
313	        RollupService.Snapshot before = rollup.snapshot(sheetId);
314	        refuseIfClosed(sheetId, claim.getDueBy());
315	        if (next == ClaimStatus.OPEN) refuseOverCap(sheetId, claim);
316	        if (next == ClaimStatus.OPEN && overReviewThreshold(sheetId, claim, opening)) next = ClaimStatus.REVIEW;
317	        switch (next) {
318	            case OPEN -> {
319	                number(numbering, claim);
320	                claim.setOpenedBy(user.strip());
321	            }
322	            case REVIEW -> {
323	                claim.setOpenedBy(user.strip());
324	                claim.setReviewOn(sheets.today(sheetId));
325	            }
326	            case SETTLED -> {
327	                claim.setSettledDue(settling);
328	                claim.setSettleBatch(null);
329	            }
330	            case PENDING -> claim.setSettleBatch(null);
331	            case VOID -> claim.setVoidReason(voidReason);
332	            default -> {}
333	        }
334	        claim.setStatus(next);
335	        logStatus(sheetId, user, person, claim);
336	        Claim saved = claims.saveAndFlush(claim);
337	        String event = switch (next) {
338	            case OPEN -> "CLAIM_OPENED";
339	            case REVIEW -> "CLAIM_REVIEW";
340	            case PENDING -> "CLAIM_PENDING";
341	            case SETTLED -> "CLAIM_SETTLED";
342	            case VOID -> "CLAIM_VOIDED";
343	            case DRAFT, DELETED -> throw new IllegalStateException();
344	        };
345	        String due = next == ClaimStatus.SETTLED
346	                ? " due=" + (saved.getSettledDue() == null ? "n/a" : saved.getSettledDue().setScale(2).toPlainString())
347	                : voidingSettled ? " reversed=" + figureText(saved.getSettledDue())
348	                : "";
349	        if (voidReason != null) due += " reason=" + voidReason;
350	        if (next == ClaimStatus.SETTLED && asOf != null) due += " on=" + asOf.on();
351	        record(event, sheetId, user, person, saved, saved.getNumber(), due);
352	        if (next == ClaimStatus.SETTLED) notifyWatchers(sheetId, user, person, saved);
353	        rollup.recordChanges(sheetId, user, before);
354	        return saved;
355	    }
