463	    /**
464	     * A steward re-settles a SETTLED claim: its due fixed again at the figure it would have today as an
465	     * open claim bound by no statement (the rate, grade, floor and late percent in force on its date, the
466	     * late charge as of today). Refused for anyone
467	     * else, a claim in any other status, or one due inside a closed period.
468	     */
469	    @Transactional
470	    public Claim resettle(String sheetId, String user, Long id) {
471	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
472	        RollupService.Snapshot before = rollup.snapshot(sheetId);
473	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
474	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusRefusedException();
475	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
476	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
477	        refuseIfClosed(sheetId, claim.getDueBy());
478	        BigDecimal old = claim.getSettledDue();
479	        BigDecimal figure = LateCharge.withChargeAsOpen(claim, floored(sheetId, claim, dueOf(sheetId, person, claim)),
480	                sheets.today(sheetId), graceOf(sheetId, person, claim), d -> settings.latePctOn(sheetId, d),
481	                roundingOf(sheetId, claim));
482	        claim.setSettledDue(figure);
483	        logStatus(sheetId, user, person, claim);
484	        Claim saved = claims.saveAndFlush(claim);
485	        record("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber(),
486	                " old=" + figureText(old) + " new=" + figureText(figure));
487	        notifyWatchers(sheetId, user, person, saved);
488	        rollup.recordChanges(sheetId, user, before);
489	        return saved;
