492	    /**
493	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure bound by a
494	     * statement stays bound; its period, which follows its due-by, stays too. While the sheet numbers by
495	     * period and the claim was numbered within another period, it takes the next number of its due-by's
496	     * period, its old number never given again. Refused for anyone else, a claim in any other status, one
497	     * due inside a closed period, or a new date after its person's retirement date.
498	     */
499	    @Transactional
500	    public Claim redate(String sheetId, String user, Long id, LocalDate date) {
501	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
502	        Sheet numbering = sheets.lockForNumbering(sheetId);
503	        RollupService.Snapshot before = rollup.snapshot(sheetId);
504	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
505	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
506	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
507	        refuseIfClosed(sheetId, claim.getDueBy());
508	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
509	        if (!person.mayClaimOn(date)) throw new PersonRetiredException();
510	        LocalDate old = claim.getDate();
511	        String oldPeriod = claim.getNumberPeriod() != null ? claim.getNumberPeriod() : periodOn(sheetId, claim.getDueBy());
512	        claim.setDate(date);
513	        if (numbering.numbersByPeriod() && !oldPeriod.equals(periodOn(sheetId, claim.getDueBy()))) {
514	            if (claim.getNumberPeriod() != null) {
515	                claims.retireNumberWithin(sheetId, claim.getNumberPeriod(), claim.getNumberSeq());
516	            }
517	            number(numbering, claim);
518	        }
519	        Claim saved = claims.saveAndFlush(claim);
520	        record("CLAIM_REDATED", sheetId, user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
521	        rollup.recordChanges(sheetId, user, before);
522	        return saved;
523	    }
