526	     * Refuse voiding a SETTLED claim unless by a steward within {@value #VOID_SETTLED_DAYS} days of its
527	     * settlement (its status log's last SETTLED date) by the sheet's today.
528	     */
529	    private void refuseVoidOfSettled(String sheetId, String user, Claim claim) {
530	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
