600	    /**
601	     * Split an amount (more than 0.00 and less than its amount) off an OPEN claim, by a user whose role may
602	     * open a claim. The claim keeps the rest of its amount and loses any figure a statement bound it to; the
603	     * new claim is OPEN with the split-off amount, the same date and note, the sheet's next number, opened
604	     * by the user, with its due-by fixed now from the terms in force on the date, and names the original's
605	     * number as split from, a late entry when its due-by falls in a soft-closed period. Refused for a claim
606	     * not OPEN, a deferred one, or one due inside a closed period (judged by the original alone).
607	     */
608	    @Transactional
609	    public Split split(String sheetId, String user, Long id, BigDecimal amount) {
610	        // Numbering locks the sheet first, so the claim is read once no other change is under way.
611	        Sheet numbering = sheets.lockForNumbering(sheetId);
612	        RollupService.Snapshot before = rollup.snapshot(sheetId);
613	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
614	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusRefusedException();
615	        if (claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimDeferredException();
616	        if (!settings.mayDo(sheetId, user, "open")) throw new ClaimNotPermittedException();
617	        refuseIfClosed(sheetId, claim.getDueBy());
618	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitRefusedException();
619	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
620	        LocalDate on = claim.getDate();
621	        claim.setAmount(claim.getAmount().subtract(amount));
622	        claim.unstate(sheets.today(sheetId));
623	        Claim original = claims.saveAndFlush(claim);
624	        int terms = termsOf(sheetId, person, sheets.today(sheetId));
625	        LocalDate dueBy = holidays.businessDaysAfter(sheetId, on, terms);
626	        Claim split = new Claim(sheetId, person.getId(), amount, on, original.getNote(), dueBy, terms);
627	        split.setSplitFrom(original.getNumber());
628	        split.setTags(original.getTags());
629	        split.setLateEntry(periods.softClosedOn(sheetId, dueBy));
630	        number(numbering, split);
631	        split.setOpenedBy(user.strip());
632	        split.setEditedBy(original.getEditedBy());
633	        split.setStatus(ClaimStatus.OPEN);
634	        split = claims.saveAndFlush(split);
635	        logStatus(sheetId, user, person, split);
636	        split = claims.saveAndFlush(split);
637	        record("CLAIM_SPLIT", sheetId, user, person, original, original.getNumber(), " into=" + split.getNumber());
638	        record("CLAIM_OPENED", sheetId, user, person, split);
639	        rollup.recordChanges(sheetId, user, before);
640	        return new Split(original, split);
641	    }
