689	        RollupService.Snapshot before = rollup.snapshot(sheetId);
690	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
691	        if (!claim.getStatus().isOpen()) throw new ClaimStatusRefusedException();
692	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
693	        if (claim.isWaived()) throw new ClaimWaivedException();
694	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
695	        claim.waive(sheets.today(sheetId));
696	        Claim saved = claims.saveAndFlush(claim);
697	        record("CLAIM_WAIVED", sheetId, user, person, saved);
698	        rollup.recordChanges(sheetId, user, before);
699	        return saved;
700	    }
701	
702	    /**
703	     * Raise a claim's proofs count by one, with a proof of the kind (null: none chosen, a receipt); the audit
704	     * line gains the kind when one was chosen. Refused for a SETTLED, VOID or DELETED claim, or one due inside a closed period.
705	     */
706	    @Transactional
707	    public Claim addProof(String sheetId, String user, Long id, String kind) {
708	        // The snapshot locks the sheet first, so the claim is read once no other change is under way.
709	        RollupService.Snapshot before = rollup.snapshot(sheetId);
710	        Claim claim = claims.findByIdAndSheetId(id, sheetId).orElseThrow(ClaimNotFoundException::new);
711	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
712	                || claim.getStatus() == ClaimStatus.DELETED) {
713	            throw new ClaimStatusRefusedException();
714	        }
715	        refuseIfClosed(sheetId, claim.getDueBy());
716	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow(PersonNotFoundException::new);
717	        claim.addProof(kind);
718	        Claim saved = claims.saveAndFlush(claim);
719	        record("CLAIM_PROOF_ADDED", sheetId, user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs()
720	                + (kind == null ? "" : " kind=" + kind));
721	        rollup.recordChanges(sheetId, user, before);
722	        return saved;
723	    }
724	
725	    /**
726	     * Add a line to a DRAFT claim: its amount becomes its lines' quantities times their unit amounts added
727	     * up, and the claim counts as edited by the user. Refused for a claim in any other status, one due
